  const cut = s.lastIndexOf(':');
  const [expr, l] = cut > 0 && /^(\d+|s)$/i.test(s.slice(cut + 1).trim())
    ? [s.slice(0, cut), s.slice(cut + 1)] : [s, ''];
  const str = /^s$/i.test((l || '').trim());
  return { expr: (expr || '').trim(), len: str ? 0 : (parseInt(l) || 4), str };
